package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;

import org.junit.jupiter.api.Test;

class ArchivePathSupportMutaGate1Test {

  @Test
  void pathSegmentsDropsEmptyInteriorSegments() {
    assertArrayEquals(
        new String[] {"a", "b", "c"}, ArchivePathSupport.pathSegments("a//b///c"));
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class ArchivePathSupportMutaGate2Test {

  @Test
  void noLeadingSeparatorWhenFirstPartIsEmpty() {
    ArchivePathSupport.ParsedUnixPath emptyFirst = ArchivePathSupport.parse("", "a", "b");
    assertEquals("a/b", emptyFirst.relativeEntryKey());

    ArchivePathSupport.ParsedUnixPath rootFirst = ArchivePathSupport.parse("/", "a");
    assertTrue(rootFirst.absolute());
    assertEquals("a", rootFirst.relativeEntryKey());

    ArchivePathSupport.ParsedUnixPath nonEmptyFirst = ArchivePathSupport.parse("x", "y");
    assertEquals("x/y", nonEmptyFirst.relativeEntryKey());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class ArchivePathSupportMutaGate3Test {

  @Test
  void parseStripsLeadingSlashOnlyForAbsolutePaths() {
    ArchivePathSupport.ParsedUnixPath absolute = ArchivePathSupport.parse("/a/b", "c");
    assertTrue(absolute.absolute());
    assertEquals("a/b/c", absolute.relativeEntryKey());

    ArchivePathSupport.ParsedUnixPath relative = ArchivePathSupport.parse("a/b", "c");
    assertFalse(relative.absolute());
    assertEquals("a/b/c", relative.relativeEntryKey());

    ArchivePathSupport.ParsedUnixPath empty = ArchivePathSupport.parse("");
    assertFalse(empty.absolute());
    assertEquals("", empty.relativeEntryKey());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class ArchivePathSupportMutaGate4Test {

  @Test
  void parseKeepsNonEmptyFirstPart() {
    ArchivePathSupport.ParsedUnixPath relative = ArchivePathSupport.parse("a", "b");
    assertFalse(relative.absolute());
    assertEquals("a/b", relative.relativeEntryKey());

    ArchivePathSupport.ParsedUnixPath single = ArchivePathSupport.parse("dir");
    assertEquals("dir", single.relativeEntryKey());

    ArchivePathSupport.ParsedUnixPath absolute = ArchivePathSupport.parse("/x", "y");
    assertTrue(absolute.absolute());
    assertEquals("x/y", absolute.relativeEntryKey());

    ArchivePathSupport.ParsedUnixPath root = ArchivePathSupport.parse("/", "y");
    assertTrue(root.absolute());
    assertEquals("y", root.relativeEntryKey());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;

import org.junit.jupiter.api.Test;

class ArchivePathSupportMutaGate5Test {

  @Test
  void pathSegmentsStripsTrailingSlashesAndHandlesEmptyResults() {
    assertArrayEquals(new String[] {"a", "b"}, ArchivePathSupport.pathSegments("a/b///"));
    assertArrayEquals(new String[] {"a", "b"}, ArchivePathSupport.pathSegments("/a/b/"));
    assertArrayEquals(new String[] {"a", "b"}, ArchivePathSupport.pathSegments("a\\b\\"));
    assertArrayEquals(new String[] {"a"}, ArchivePathSupport.pathSegments("a"));
    assertArrayEquals(new String[0], ArchivePathSupport.pathSegments("/"));
    assertArrayEquals(new String[0], ArchivePathSupport.pathSegments("///"));
    assertArrayEquals(new String[0], ArchivePathSupport.pathSegments(""));
    assertArrayEquals(new String[0], ArchivePathSupport.pathSegments(null));
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;

import org.junit.jupiter.api.Test;

class ArchivePathSupportMutaGate6Test {

  @Test
  void pathSegmentsStripsTrailingSlashes() {
    assertArrayEquals(new String[] {"a", "b"}, ArchivePathSupport.pathSegments("a/b/"));
    assertArrayEquals(new String[] {"dir", "sub"}, ArchivePathSupport.pathSegments("/dir/sub//"));
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;

import org.junit.jupiter.api.Test;

class ArchivePathSupportMutaGate7Test {

  @Test
  void pathSegmentsKeepsLastSegmentAndStripsTrailingSlashes() {
    assertArrayEquals(new String[] {"a", "b"}, ArchivePathSupport.pathSegments("a/b"));
    assertArrayEquals(new String[] {"a", "b"}, ArchivePathSupport.pathSegments("a/b/"));
    assertArrayEquals(new String[] {"a", "b"}, ArchivePathSupport.pathSegments("/a/b//"));
    assertArrayEquals(new String[0], ArchivePathSupport.pathSegments("///"));
  }
}

